	zip.Describe("github.com/hanzoai/cloud/apps/platform GET /v1/platform/projects/:project/apps/:app/deployments", zip.Doc{
		Description: "Returns an app's deployment history.\n\nIt lists every deployment recorded for one of the caller org's applications,\nnewest version first, each with its version, status, source, commit and image.\nFailed and superseded attempts are included — that is the point of a history.\nRequires a validated principal; 401 without one.",
		Fields: map[string]string{
			"appRef.app":                   "App is the application's slug, from the path.",
			"appRef.project":               "Project is the project the application lives under, from the path.",
			"deploymentView.applicationId": "ApplicationID is the app this deployed — the app's `id`, not its slug.",
			"deploymentView.buildId":       "BuildID is the build record behind a git deploy, whose logs and status live\nat /v1/platform/builds. Empty for an image deploy.",
			"deploymentView.commit":        "Commit is the git ref this built — the commit a deploy or a push named,\nelse the app's branch. Empty for an image deploy, which builds nothing.",
			"deploymentView.createdAt":     "CreatedAt is when the attempt was recorded, unix seconds.",
			"deploymentView.id":            "ID is the deployment's id (`dep_…`), minted when the attempt is recorded.\nThe app's currentDeploymentId points at one of these.",
			"deploymentView.image":         "Image is the full `repo:tag` this deployment put in the CR. For a git deploy\nit is the ref the in-cluster build pushes to, known before the build runs.",
			"deploymentView.message":       "Message is why this attempt is not live: the failure, or the note that a\nnewer deployment went live before this build finished. Empty while it is fine.",
			"deploymentView.org":           "Org is the tenant the deployment belongs to, from the validated identity.",
			"deploymentView.source":        "Source is which lane produced it: `git` (built from the repo) or `image`\n(an already-built ref deployed as-is, including promote and rollback).",
			"deploymentView.status":        "Status is where the attempt got to: `building` while its image is being\nbuilt, `deploying` once its CR reached the cluster — which is the terminal\nsuccess state, the app's own status is what turns `live` — `error` with the\nreason in Message, or `superseded` when a newer version went live first.",
			"deploymentView.updatedAt":     "UpdatedAt is its last transition, unix seconds — so for a terminal\ndeployment it is when it reached that state.",
			"deploymentView.version":       "Version counts this app's deployments, from 1 and monotonically. It is what\nORDERS them: a deploy only goes live if no higher version already is, so a\nbuild that finishes late is superseded instead of overwriting a newer one.",
		},
	})
